const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Lake Killamperpunna, South Australia. A rectangle is used to encompass the lake.
  const aoi = ee.Geometry.Rectangle([138.70, -28.30, 138.95, -28.10]);

  // The question asks about a period in the future (2025).
  // Define a "start" and "end" period within the given timeframe.
  const startDate = '2025-06-20';
  const endDate = '2025-09-15';
  const startPeriod = ee.DateRange(startDate, ee.Date(startDate).advance(15, 'day'));
  const endPeriod = ee.DateRange(ee.Date(endDate).advance(-15, 'day'), endDate);

  // 2. Data Acquisition & Check
  const s2Collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED');

  const colStart = s2Collection.filterBounds(aoi).filterDate(startPeriod);
  const colEnd = s2Collection.filterBounds(aoi).filterDate(endPeriod);

  // Check if images exist for the specified future dates.
  const startSize = colStart.size().getInfo();
  const endSize = colEnd.size().getInfo();

  console.log(`Images found for start period (June 2025): ${startSize}`);
  console.log(`Images found for end period (Sep 2025): ${endSize}`);

  // Since the date is in the future, no images will be found.
  if (startSize === 0 || endSize === 0) {
    console.log("Error: No images found. The requested dates are in the future.");
    console.log("C1: Empty Collection");
  } else {
      // This block is unreachable for the given question but included for logical completeness.
      // Define a cloud masking function
      const maskS2clouds = function(image) {
        const qa = image.select('QA60');
        const cloudBitMask = 1 << 10;
        const cirrusBitMask = 1 << 11;
        const mask = qa.bitwiseAnd(cloudBitMask).eq(0).and(qa.bitwiseAnd(cirrusBitMask).eq(0));
        return image.updateMask(mask).divide(10000)
                    .select("B3", "B8")
                    .copyProperties(image, ["system:time_start"]);
      };

      // Define a function to calculate water pixels
      const getWaterExtent = function(image) {
        const ndwi = image.normalizedDifference(['B3', 'B8']).rename('ndwi');
        const water = ndwi.gt(0.0); // A common threshold for NDWI
        const waterPixels = water.reduceRegion({
            reducer: ee.Reducer.sum(),
            geometry: aoi,
            scale: 100, // Use a larger scale for regional analysis
            maxPixels: 1e9
        });
        return ee.Number(waterPixels.get('ndwi'));
      };

      const startImage = colStart.map(maskS2clouds).median();
      const endImage = colEnd.map(maskS2clouds).median();

      const startWater = getWaterExtent(startImage).getInfo();
      const endWater = getWaterExtent(endImage).getInfo();

      console.log(`Start Period Water Pixels: ${startWater}`);
      console.log(`End Period Water Pixels: ${endWater}`);

      if (endWater > startWater) {
        console.log("A");
      } else {
        console.log("B");
      }
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Initialization or analysis failed: ${e}`);
    console.error("D");
  }
}

initEE().catch(e => {
    console.error(`Unhandled error: ${e}`);
    console.error("D");
});
